import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    vals = list(map(int, data))
    idx = 0
    n = vals[idx] if idx < len(vals) else 0
    idx += 1

    # try to read m; if not enough numbers remain, treat remaining as edges
    m = 0
    if idx < len(vals):
        # if remaining count fits m*3 after reading a possible m, use it
        possible_m = vals[idx]
        if len(vals) - (idx + 1) >= possible_m * 3:
            m = possible_m
            idx += 1
        else:
            # treat all remaining numbers as edge triples
            m = (len(vals) - idx) // 3
    else:
        m = 0

    edges = []
    for _ in range(m):
        if idx + 2 >= len(vals):
            break
        u = vals[idx] - 1
        v = vals[idx + 1] - 1
        w = vals[idx + 2]
        edges.append((w, u, v))
        idx += 3

    if n <= 0:
        print(0)
        return

    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    edges.sort()
    total = 0
    taken = 0
    for w, u, v in edges:
        if 0 <= u < n and 0 <= v < n and union(u, v):
            total += w
            taken += 1
            if taken == n - 1:
                break

    if taken == n - 1:
        print(total)
    else:
        print(-1)


if __name__ == "__main__":
    solve()
